{"conversation":"I think I am assuming that lamps stay on even after queries. But the problem says lamps that are on at the query cell and its adjacent cells should be turned off after answering each query. So I didn't implement the turning off of lamps yet.","python_code":"from collections import defaultdict

class Solution:
    def gridIllumination(self, n: int, lamps: List[List[int]], queries: List[List[int]]) -> List[int]:
        row_count = defaultdict(int)
        col_count = defaultdict(int)
        diag_count = defaultdict(int)  # main diagonal: r - c
        anti_diag_count = defaultdict(int)  # anti diagonal: r + c

        # Keep set of lamp positions so I can turn them off later
        lamp_set = set()
        for r, c in lamps:
            lamp_set.add((r, c))
            row_count[r] += 1
            col_count[c] += 1
            diag_count[r - c] += 1
            anti_diag_count[r + c] += 1

        ans = []
        for r, c in queries:
            if row_count[r] > 0 or col_count[c] > 0 or diag_count[r - c] > 0 or anti_diag_count[r + c] > 0:
                ans.append(1)
            else:
                ans.append(0)

            # turn off lamp at query cell and its adjacent lamps
            for nr in range(r-1, r+2):
                for nc in range(c-1, c+2):
                    if (nr, nc) in lamp_set:
                        lamp_set.remove((nr, nc))
                        row_count[nr] -= 1
                        col_count[nc] -= 1
                        diag_count[nr - nc] -= 1
                        anti_diag_count[nr + nc] -= 1

        return ans
